
const $=id=>document.getElementById(id), icon=GroveIcons;
const meetings=[{id:1,title:'제품 검토 및 다음 배포 일정 논의',folder:'제품팀',date:'10. 29. 10:30',length:'52:17'},{id:2,title:'고객 인터뷰 - 사용 경험과 개선 요청',folder:'인터뷰',date:'10. 28. 14:00',length:'38:12'},{id:3,title:'운영 개선 사항 검토',folder:'제품팀',date:'10. 27. 11:00',length:'24:08'},{id:4,title:'새로운 아이디어 메모',folder:null,date:'10. 26. 16:00',length:'12:40'}];
let mode=localStorage.getItem('nero-proposal-mode')||'folders',filter='all',selected=null,transcript=false;
$('toggleNav').innerHTML=icon('panel-left-close');$('closeNav').innerHTML=icon('panel-left-close');
function isNarrow(){return innerWidth<900||$('shell').classList.contains('half');}
function syncNav(){
 const open=!$('shell').classList.contains('collapsed'), overlay=open&&isNarrow();
 document.querySelector('main').inert=overlay;
 const aside=document.querySelector('aside');
 if(overlay){aside.setAttribute('role','dialog');aside.setAttribute('aria-modal','true');aside.setAttribute('aria-label','회의 탐색');}
 else {aside.removeAttribute('role');aside.removeAttribute('aria-modal');}
 $('toggleNav').setAttribute('aria-expanded',String(open));
}
function toggleNav(){ $('shell').classList.toggle('collapsed');localStorage.setItem('nero-proposal-nav',$('shell').classList.contains('collapsed'));syncNav();(isNarrow()&&!$('shell').classList.contains('collapsed')?$('closeNav'):$('toggleNav')).focus(); }
addEventListener('resize',syncNav);
$('toggleNav').onclick=$('closeNav').onclick=document.querySelector('.backdrop').onclick=toggleNav;
if(localStorage.getItem('nero-proposal-nav')==='true'||innerWidth<900)$('shell').classList.add('collapsed');
const recent=document.querySelector('.recent');recent.open=localStorage.getItem('nero-proposal-recents')!=='false';recent.ontoggle=()=>localStorage.setItem('nero-proposal-recents',recent.open);
$('recents').innerHTML=meetings.map(m=>`<button data-open="${m.id}"><strong title="${m.title}">${m.title}</strong><small>${m.date} / ${m.length}</small></button>`).join('');
function render(){ syncNav();$('nav').innerHTML=[['all','회의 목록','book-open',4],['unfiled','미분류','inbox',1],['제품팀','제품팀','folder',2],['인터뷰','인터뷰','folder',1],['trash','휴지통','trash-2',0]].map(([id,name,i,count])=>`<button data-filter="${id}" ${!selected&&filter===id?'aria-current="page"':''}>${icon(i)}${name}<span class="count">${count}</span></button>`).join('');$('transcriptToggle').hidden=!selected;$('transcriptToggle').setAttribute('aria-expanded',transcript);
if(selected){const m=meetings.find(m=>m.id===selected);$('page').innerHTML=`<h1>${m.title}</h1><p class="metadata">2026. ${m.date} / ${m.folder||'미분류'}</p><div class="player"><button class="quiet icon" id="play" aria-label="예시 재생 상태">${icon('play')}</button><span>0:00</span><input type="range" aria-label="재생 위치" min="0" max="3137" value="0"><span>${m.length}</span><details class="speed"><summary>1x</summary><div class="speed-menu">${[.75,1,1.25,1.5,2].map(n=>`<button data-speed="${n}">${n}x${n===1?' 선택':''}</button>`).join('')}</div></details></div><div class="detail-body"><article class="summary"><h2>요약</h2><section><h2>핵심</h2><p>녹음 안정성과 오류 복구를 우선 개선하고, 배포 전 긴 회의에서 다시 확인합니다.</p></section><section><h2>결정 사항</h2><ul><li>금요일까지 오류를 수정한 뒤 다음 주 배포 여부를 결정합니다. <button class="citation" data-cite>18:42</button></li><li>회의 요약을 기본 화면으로 유지합니다.</li></ul></section><section><h2>할 일</h2><ul><li>첫 녹음 권한과 오류 복구 흐름 점검</li><li>긴 회의 처리와 저장 상태 재검증</li></ul></section></article><section class="transcript" ${transcript?'':'hidden'}><header><h2>음성 기록</h2><button class="quiet icon" data-close-transcript aria-label="음성 기록 닫기">${icon('x')}</button></header><p class="muted">전체 기록</p><div class="utterance"><small>18:20 / 화자 1</small>지금 버전에서 녹음이 끊기는 이슈가 가끔 발생하는 것 같습니다.</div><div class="utterance active"><small>18:42 / 화자 2</small>금요일까지 오류부터 정리하고, 다음 주에 배포할 수 있을지 다시 보죠.</div><div class="utterance"><small>19:06 / 화자 1</small>그럼 요약 화면은 지금 구조를 유지하겠습니다.</div><div class="utterance"><small>20:15 / 화자 3</small>추가로 긴 회의에서도 안정적으로 처리되는지 확인이 필요합니다.</div></section></div>`;return;}
const query=$('search').value.toLowerCase();const list=meetings.filter(m=>(filter==='all'||(filter==='unfiled'?!m.folder:m.folder===filter))&&m.title.toLowerCase().includes(query));
const folders=filter==='all'&&mode==='folders'&&!query;
$('page').innerHTML=`<div class="heading"><div><h1>${filter==='all'?'회의 목록':filter==='unfiled'?'미분류':filter==='trash'?'휴지통':filter}</h1><small>${list.length}개 회의</small></div>${filter==='all'?`<div class="segmented" aria-label="회의 보기"><button data-mode="folders" aria-pressed="${mode==='folders'}">폴더별</button><button data-mode="all" aria-pressed="${mode==='all'}">전체 회의</button></div>`:''}</div>${folders?`<div class="folders">${['제품팀','인터뷰'].map(f=>`<button class="folder" data-filter="${f}">${icon('folder')}<div><strong>${f}</strong><small>${meetings.filter(m=>m.folder===f).length}개 회의</small></div></button>`).join('')}</div><p class="section-label">미분류</p>`:''}${list.filter(m=>!folders||!m.folder).map(m=>`<div class="row">${icon('audio-lines')}<button class="open" data-open="${m.id}"><strong title="${m.title}">${m.title}</strong><small>${m.date} / ${m.length}${!folders?' / '+(m.folder||'미분류'):''}</small></button><button class="quiet icon" data-open="${m.id}" aria-label="${m.title} 열기">${icon('arrow-right')}</button></div>`).join('')||'<p class="muted">회의가 없습니다.</p>'}`;
}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.open){selected=Number(t.dataset.open);transcript=false;if(innerWidth<900||$('shell').classList.contains('half'))$('shell').classList.add('collapsed');render();}if(t.dataset.filter){filter=t.dataset.filter;selected=null;if(isNarrow())$('shell').classList.add('collapsed');render();}if(t.dataset.mode){mode=t.dataset.mode;localStorage.setItem('nero-proposal-mode',mode);render();}if(t.hasAttribute('data-cite')){transcript=true;render();}if(t.hasAttribute('data-close-transcript')){transcript=false;render();$('transcriptToggle').focus();}if(t.dataset.speed){t.closest('details').querySelector('summary').textContent=t.dataset.speed+'x';t.closest('details').open=false;}if(t.id==='play'){t.innerHTML=icon(t.getAttribute('aria-pressed')==='true'?'play':'pause');t.setAttribute('aria-pressed',t.getAttribute('aria-pressed')!=='true');}});
$('home').onclick=()=>{selected=null;filter='all';render();};$('search').oninput=()=>{selected=null;filter='all';render();};$('transcriptToggle').onclick=()=>{transcript=!transcript;render();};$('width').onclick=()=>{$('shell').classList.toggle('half');$('shell').classList.add('collapsed');$('width').textContent=$('shell').classList.contains('half')?'전체 너비':'절반 너비';syncNav();};$('theme').onclick=()=>{const dark=document.documentElement.dataset.mode==='dark';document.documentElement.dataset.mode=dark?'light':'dark';$('theme').textContent=dark?'어둡게':'밝게';};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(transcript){transcript=false;render();$('transcriptToggle').focus();}else {$('shell').classList.add('collapsed');syncNav();$('toggleNav').focus();}}});$('new').disabled=true;$('new').title='탐색 구조 검토용 시안';$('settings').disabled=true;render();

document.querySelector('aside').addEventListener('keydown',event=>{
 if(event.key!=='Tab'||!isNarrow()||$('shell').classList.contains('collapsed'))return;
 const controls=[...document.querySelectorAll('aside button:not(:disabled),aside input,aside summary')].filter(node=>node.getClientRects().length);
 const first=controls[0],last=controls.at(-1);
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
});
